CREATE TABLE fuel_prices ( id bigint GENERATED BY DEFAULT AS IDENTITY CONSTRAINT fuel_prices_pk PRIMARY KEY, region_id bigint NOT NULL, fuel varchar(16) NOT NULL, source varchar(16) NOT NULL, frequency varchar(16) NOT NULL, provider varchar(16) NOT NULL, reference_date date NOT NULL, price_rub_per_liter numeric NOT NULL, publication_date date, loaded_at timestamp with time zone NOT NULL, version bigint NOT NULL DEFAULT 0, CONSTRAINT fuel_prices_fk1 FOREIGN KEY (region_id) REFERENCES regions(id), CONSTRAINT fuel_prices_uk1 UNIQUE (region_id, fuel, source, reference_date), CONSTRAINT fuel_prices_ck1 CHECK (fuel IN ('DIESEL', 'AI_92', 'AI_95')), CONSTRAINT fuel_prices_ck2 CHECK ( (source = 'OFFICIAL' AND frequency = 'WEEKLY' AND provider IN ('ROSSTAT', 'RUSTATA')) OR (source = 'MARKET' AND frequency = 'DAILY' AND provider = 'BENZUP') ), CONSTRAINT fuel_prices_ck3 CHECK ( price_rub_per_liter > 0 AND price_rub_per_liter NOT IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric) AND length(price_rub_per_liter::text) <= 64 ) ); CREATE INDEX fuel_prices_idx1 ON fuel_prices(source, fuel, reference_date, region_id);
-- Retain current weekly statistics and daily market snapshots; merge duplicate official delivery channels. INSERT INTO fuel_prices ( region_id, fuel, source, frequency, provider, reference_date, price_rub_per_liter, publication_date, loaded_at ) SELECT retained.region_id, retained.fuel_type_code, retained.source, retained.frequency, retained.provider_code, retained.reference_date, retained.price_rub_per_liter, retained.publication_date, retained.loaded_at FROM ( SELECT price.region_id, price.fuel_type_code, CASE WHEN price.provider_code = 'BENZUP' THEN 'MARKET' ELSE 'OFFICIAL' END AS source, period.frequency, price.provider_code, period.reference_date, observation.price_rub_per_liter, publication.publication_date, publication.loaded_at, ROW_NUMBER() OVER ( PARTITION BY price.region_id, price.fuel_type_code, period.reference_date, CASE WHEN price.provider_code = 'BENZUP' THEN 'MARKET' ELSE 'OFFICIAL' END ORDER BY CASE WHEN price.provider_code = 'ROSSTAT' THEN 0 ELSE 1 END, publication.loaded_at DESC, observation.id DESC ) AS position FROM regional_price_keys price INNER JOIN price_periods period ON price.period_id = period.id INNER JOIN regional_price_observations observation ON price.current_observation_id = observation.id INNER JOIN source_publications publication ON observation.publication_id = publication.id WHERE observation.price_rub_per_liter > 0 AND ((price.provider_code IN ('ROSSTAT', 'RUSTATA') AND period.frequency = 'WEEKLY') OR (price.provider_code = 'BENZUP' AND period.frequency = 'DAILY')) ) retained WHERE retained.position = 1;
CREATE TABLE import_states ( code varchar(32) CONSTRAINT import_states_pk PRIMARY KEY, content_hash varchar(64), fetched_through date, last_success_at timestamp with time zone, last_attempt_at timestamp with time zone, error_message text );
